import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { createHmac, timingSafeEqual as nodeTimingSafeEqual } from 'crypto';

/**
 * Deploy diff (this release), .env fragment:
 *
 *   - UNSUBSCRIBE_SECRET=whsec_8f2a1c9d4b7e3f01a6c9d2b5e8f10a3c
 *   + UNSUBSCRIBE_SECRET=whsec_1d4e7a90c3b6f29d5a8e1c4b7f0a3d6e
 *
 * Rotated as routine credential hygiene. No other lines in the diff touch
 * apps/email/src/unsubscribe/*.
 */

export interface UnsubscribePayload {
  userId: string;
  listId: string;
  iat: number;
}

const TOKEN_TTL_MS = 90 * 24 * 60 * 60 * 1000; // 90 days

@Injectable()
export class UnsubscribeTokenService {
  private readonly secret: string;

  constructor(private readonly config: ConfigService) {
    this.secret = this.config.getOrThrow<string>('UNSUBSCRIBE_SECRET');
  }

  /**
   * Mints a stateless unsubscribe token embedded in outbound emails.
   * `payload` is `${userId}.${listId}.${iat}`, base64url-encoded upstream.
   */
  sign(payload: string): string {
    const signature = createHmac('sha256', this.secret)
      .update(payload)
      .digest('base64url');

    return `${payload}.${signature}`;
  }

  /**
   * Verifies a token from an incoming unsubscribe request.
   * Returns the decoded payload if the signature and TTL both check out,
   * otherwise null (surfaced to the user as "invalid or expired").
   */
  verify(token: string): UnsubscribePayload | null {
    const lastDotIndex = token.lastIndexOf('.');
    if (lastDotIndex === -1) {
      return null;
    }

    const payload = token.slice(0, lastDotIndex);
    const carriedSignature = token.slice(lastDotIndex + 1);

    const expected = createHmac('sha256', this.secret)
      .update(payload)
      .digest('base64url');

    if (!this.timingSafeEqual(expected, carriedSignature)) {
      return null;
    }

    const decoded = this.decodePayload(payload);
    if (!decoded) {
      return null;
    }

    const age = Date.now() - decoded.iat;
    if (age > TOKEN_TTL_MS) {
      return null;
    }

    return decoded;
  }

  private timingSafeEqual(expected: string, carried: string): boolean {
    const expectedBuf = Buffer.from(expected);
    const carriedBuf = Buffer.from(carried);

    if (expectedBuf.length !== carriedBuf.length) {
      return false;
    }

    return nodeTimingSafeEqual(expectedBuf, carriedBuf);
  }

  private decodePayload(payload: string): UnsubscribePayload | null {
    const [userId, listId, iatRaw] = payload.split('.');
    const iat = Number(iatRaw);

    if (!userId || !listId || Number.isNaN(iat)) {
      return null;
    }

    return { userId, listId, iat };
  }
}

