import {
  Controller,
  Delete,
  Head,
  Param,
  Patch,
  Post,
  Req,
  Res,
  UseGuards,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { Server } from '@tus/server';
import { FileStore } from '@tus/file-store';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';

@Controller('files')
export class UploadController {
  private readonly tusServer = new Server({
    path: '/files',
    datastore: new FileStore({ directory: './uploads' }),
  });

  /**
   * Create an upload session. Auth is enforced ONLY here: the guard
   * validates the bearer/JWT access token that was current at the moment
   * the client started the upload. Nothing re-checks or refreshes that
   * token on any later request against this same upload id.
   */
  @UseGuards(JwtAuthGuard)
  @Post()
  create(@Req() req: Request, @Res() res: Response) {
    return this.tusServer.handle(req, res);
  }

  /**
   * Send a chunk (may happen minutes, hours, or days after `create`, once
   * per resume). No guard is applied. Because this route is declared on
   * the Nest controller like any other, the request also passes through
   * the same request pipeline wired up in main.ts — including the global
   * body parser — before `tusServer.handle` ever touches the raw bytes.
   */
  @Patch(':id')
  uploadChunk(@Req() req: Request, @Res() res: Response) {
    return this.tusServer.handle(req, res);
  }

  /**
   * Query the current offset so the client knows where to resume from.
   * No guard is applied here either.
   */
  @Head(':id')
  getOffset(@Req() req: Request, @Res() res: Response) {
    return this.tusServer.handle(req, res);
  }

  /**
   * Abort/cleanup an in-progress upload. No guard is applied here either.
   */
  @Delete(':id')
  abort(@Req() req: Request, @Res() res: Response) {
    return this.tusServer.handle(req, res);
  }
}

