import { Injectable, BadRequestException, NotFoundException } from "@nestjs/common"
import { createHash } from "crypto"
import { promises as fs, createWriteStream } from "fs"
import * as path from "path"

/**
 * In-memory bookkeeping for one in-flight upload.
 */
interface UploadSession {
  uploadId: string
  totalChunks: number
  receivedChunks: number[]
  sourceChecksum: string
}

const TMP_ROOT = path.join(process.cwd(), "tmp", "uploads")

@Injectable()
export class UploadService {
  private readonly sessions = new Map<string, UploadSession>()

  /**
   * Starts a new upload session and creates its per-upload temp directory.
   */
  async startUpload(uploadId: string, totalChunks: number, sourceChecksum: string): Promise<void> {
    const dir = this.uploadDir(uploadId)
    await fs.mkdir(dir, { recursive: true })

    this.sessions.set(uploadId, {
      uploadId,
      totalChunks,
      receivedChunks: [],
      sourceChecksum,
    })
  }

  /**
   * Writes one chunk to disk and records its arrival in the session.
   * Called on every PATCH /uploads/:uploadId/chunks — including retries
   * the client fires after a flaky-network timeout.
   */
  async writeChunk(uploadId: string, chunkIndex: number, data: Buffer): Promise<void> {
    const session = this.sessions.get(uploadId)
    if (!session) {
      throw new NotFoundException(`Upload session not found: ${uploadId}`)
    }

    const partPath = this.partPath(uploadId, chunkIndex)

    // Persist the chunk bytes for this index.
    await new Promise<void>((resolve, reject) => {
      // NOTE: flags "a" appends to whatever is already on disk for this index.
      // A resent chunkIndex lands on top of the bytes from the previous
      // delivery instead of replacing them.
      const stream = createWriteStream(partPath, { flags: "a" })
      stream.on("finish", resolve)
      stream.on("error", reject)
      stream.end(data)
    })

    // Record that this index has arrived.
    session.receivedChunks.push(chunkIndex)
  }

  /**
   * Assembles the final file once every chunk has arrived and verifies
   * its checksum against the one the client supplied at startUpload.
   */
  async finalize(uploadId: string): Promise<{ filePath: string; checksum: string }> {
    const session = this.sessions.get(uploadId)
    if (!session) {
      throw new NotFoundException(`Upload session not found: ${uploadId}`)
    }

    if (session.receivedChunks.length !== session.totalChunks) {
      const missingCount = session.totalChunks - session.receivedChunks.length
      throw new BadRequestException(`Upload incomplete: missing ${missingCount} chunk(s)`)
    }

    const finalPath = path.join(TMP_ROOT, `${uploadId}.bin`)
    const output = createWriteStream(finalPath)

    for (let index = 0; index < session.totalChunks; index++) {
      const partPath = this.partPath(uploadId, index)
      const partData = await fs.readFile(partPath)
      await new Promise<void>((resolve, reject) => {
        output.write(partData, (err) => (err ? reject(err) : resolve()))
      })
    }
    await new Promise<void>((resolve) => output.end(resolve))

    const finalBytes = await fs.readFile(finalPath)
    const checksum = createHash("sha256").update(finalBytes).digest("hex")

    if (checksum !== session.sourceChecksum) {
      throw new BadRequestException(
        `Checksum mismatch: expected ${session.sourceChecksum}, got ${checksum}`,
      )
    }

    this.sessions.delete(uploadId)
    return { filePath: finalPath, checksum }
  }

  private uploadDir(uploadId: string): string {
    return path.join(TMP_ROOT, uploadId)
  }

  private partPath(uploadId: string, chunkIndex: number): string {
    return path.join(this.uploadDir(uploadId), `${chunkIndex}.part`)
  }
}

