// tracing.interceptor.ts
import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Request } from 'express';
import { trace } from '@opentelemetry/api';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';

const tracer = trace.getTracer('orders-api-http');

/**
 * Wraps every incoming HTTP request in a span so failed or slow requests
 * can be traced end to end.
 */
@Injectable()
export class TracingInterceptor implements NestInterceptor {
  intercept(ctx: ExecutionContext, next: CallHandler): Observable<unknown> {
    const req = ctx.switchToHttp().getRequest<Request>();

    const span = tracer.startSpan(`HTTP ${req.method}`);

    // Concrete URL, including path params like the order id and the raw query string.
    // e.g. /orders/8f3a1c2e-91d4-4b7a-9c3e-2a6f1d0b7e55/items?expand=lineItems&currency=USD
    span.setAttribute('http.url', req.originalUrl);

    // Caller's freeform search text, copied verbatim into the span.
    span.setAttribute('user.query', req.body?.search ?? '');

    return next.handle().pipe(
      tap({
        next: () => span.end(),
        error: (err) => {
          span.recordException(err);
          span.end();
        },
      }),
    );
  }
}

import { randomBytes } from 'crypto';
import { Request, Response, NextFunction } from 'express';
import {
  Injectable,
  CanActivate,
  ExecutionContext,
  NestMiddleware,
  Module,
  MiddlewareConsumer,
} from '@nestjs/common';
import { APP_GUARD } from '@nestjs/core';

// ── 1. Nonce minting ────────────────────────────────────────────────
// A CanActivate guard: Nest runs guards AFTER all middleware.
// This piece looks correct in isolation — and it is.
@Injectable()
export class NonceGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest<Request>();
    const res = context.switchToHttp().getResponse<Response>();

    const nonce = randomBytes(16).toString('base64');

    // Stash the nonce so downstream consumers (header + template) can use it.
    (req as any).cspNonce = nonce;
    res.locals.nonce = nonce;

    return true;
  }
}

function buildPolicy(nonce: string | undefined): string {
  return `default-src 'self'; script-src 'self' 'nonce-${nonce ?? ''}'; report-uri /csp-report`;
}

// ── 2. Header builder ───────────────────────────────────────────────
// NestMiddleware: Nest runs middleware BEFORE guards, so req.cspNonce
// has not been written yet when this callback fires.
@Injectable()
export class CspHeaderMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction): void {
    const nonce = (req as any).cspNonce; // undefined — NonceGuard hasn't run yet
    res.setHeader('Content-Security-Policy-Report-Only', buildPolicy(nonce));
    next();
  }
}

// ── 3. View template (rendered by the controller, LATE) ────────────
// page.hbs — renders after the guard has already run, so it sees the
// real minted value:
//
//   <script nonce="{{nonce}}">
//     initPage();
//   </script>

// ── 4. Wiring ────────────────────────────────────────────────────────
// CspHeaderMiddleware is declared "first" in this file, and NonceGuard
// is registered as a global guard below — but Nest's fixed phase order
// (middleware → guards → interceptors → controller) means declaration
// order in the source does NOT equal execution order.
@Module({
  providers: [{ provide: APP_GUARD, useClass: NonceGuard }],
})
export class AppModule {
  configure(consumer: MiddlewareConsumer): void {
    consumer.apply(CspHeaderMiddleware).forRoutes('*');
  }
}

// Rollout history: this policy shipped two weeks ago as
// `Content-Security-Policy-Report-Only` pointed at a /csp-report
// collector. In report-only mode nothing is ever blocked, so every
// page load quietly fired a violation into that stream — it was never
// triaged, just noise — until yesterday, when the header name was
// flipped to `Content-Security-Policy` (enforce mode). That flip did
// not introduce the bug; it revealed it.

