import { Injectable, Logger } from '@nestjs/common';

export interface ScanResult {
  blocked: boolean;
  reason: string;
}

export interface AuditEntry {
  decision: 'blocked' | 'allowed';
  reason?: string;
  prompt: string;
}

export interface CompletionResult {
  status: 'ok' | 'blocked';
  text?: string;
  reason?: string;
}

export interface RedactionService {
  /** Strips PII from `text` and returns the cleaned string. */
  redactPii(text: string): string;
}

export interface InjectionScannerService {
  /** Classifies `text`; can throw if the backing classifier is unavailable. */
  scan(text: string): ScanResult;
}

export interface LlmProviderService {
  complete(text: string): Promise<string>;
}

export interface AuditLogService {
  write(entry: AuditEntry): void;
}

@Injectable()
export class LlmSafetyGateService {
  private readonly logger = new Logger(LlmSafetyGateService.name);

  constructor(
    private readonly redactionService: RedactionService,
    private readonly injectionScanner: InjectionScannerService,
    private readonly provider: LlmProviderService,
    private readonly auditLog: AuditLogService,
  ) {}

  /**
   * Safety gate every outbound LLM call must pass through: blocks prompt
   * injection, strips PII before the prompt reaches the external provider,
   * and records an audit trail of the allow/block decision.
   */
  async guardedComplete(userPrompt: string): Promise<CompletionResult> {
    const redacted = this.redactionService.redactPii(userPrompt);

    try {
      const scanResult = this.injectionScanner.scan(redacted);

      if (scanResult.blocked) {
        this.auditLog.write({
          decision: 'blocked',
          reason: scanResult.reason,
          prompt: userPrompt,
        });

        return { status: 'blocked', reason: scanResult.reason };
      }
    } catch (err) {
      // Classifier had an outage - don't fail the request over it.
      this.logger.warn('scanner unavailable, continuing');
    }

    return { status: 'ok', text: await this.provider.complete(userPrompt) };
  }
}

