    orderId: string;
    amount: number;
    customerEmail: string;
  };
}

@Controller('webhooks')
export class PaymentWebhookController {
  constructor(
    @InjectRepository(LedgerEntry)
    private readonly ledgerRepo: Repository<LedgerEntry>,
    @InjectRepository(ProcessedEvent)
    private readonly eventRepo: Repository<ProcessedEvent>,
    private readonly mailService: MailService,
    private readonly fulfillmentService: FulfillmentService,
    private readonly analyticsService: AnalyticsService,
  ) {}

  @Post('payment')
  async handlePaymentWebhook(
    @Req() req: Request,
    @Headers('x-signature') signature: string,
    @Res() res: Response,
  ): Promise<void> {
    const rawBody = (req as any).rawBody as string;

    // Cheap, must happen before we trust anything in the payload.
    if (!this.verifySignature(rawBody, signature)) {
      throw new UnauthorizedException('Invalid webhook signature');
    }

    const event = JSON.parse(rawBody) as PaymentSucceededEvent;

    if (event.type !== 'payment.succeeded') {
      res.status(200).send();
      return;
    }

    const { orderId, amount, customerEmail } = event.data;

    // Notify the customer and kick off fulfillment before we even know
    // whether this event has already been processed.
    await this.mailService.sendConfirmationEmail(customerEmail);
    await this.fulfillmentService.fulfill(orderId);
    await this.analyticsService.trackPaymentSucceeded(orderId, amount);

    // Dedup only runs after the slow work above already fired, so a
    // redelivered event redoes all of it before we ever reach this check.
    const existing = await this.eventRepo.findOne({ where: { eventId: event.id } });
    if (existing) {
      res.status(200).send();
      return;
    }

    await this.ledgerRepo.save({ orderId, amount, status: 'PAID' });
    await this.eventRepo.save({ eventId: event.id, processedAt: new Date() });

    res.status(200).send();
  }

  private verifySignature(rawBody: string, signature: string): boolean {
    // ... HMAC comparison against the gateway's signing secret
    return true;
  }
}

