import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

import { User } from './entities/user.entity';
import { OAuthProvider } from './enums/oauth-provider.enum';
import { OAuthProfile } from './interfaces/oauth-profile.interface';
import { SessionService } from './session.service';

/**
 * Handles OAuth callbacks for every configured identity provider
 * (Google, GitHub, ...) through a single shared entry point.
 */
@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);

  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly configService: ConfigService,
    private readonly sessionService: SessionService,
  ) {}

  async handleOAuthCallback(provider: OAuthProvider, profile: OAuthProfile) {
    // Offline shortcut for local/dev, toggled purely by a runtime flag.
    if (this.configService.get<boolean>('MOCK_AUTH') === true) {
      return this.mockLogin(profile.email);
    }

    // Step 1 — re-login on the SAME provider: converge on the stable
    // provider-issued id, never create a duplicate row.
    const sameProviderUser = await this.userRepository.findOne({
      where: { provider, providerId: profile.providerId },
    });
    if (sameProviderUser) {
      return this.sessionService.issueSession(sameProviderUser);
    }

    // Step 2 — fallback that used to be safe for Google-only email
    // verification, now shared across every provider without checking
    // which provider actually verified this email.
    const existingUser = await this.userRepository.findOne({
      where: { email: profile.email },
    });
    if (existingUser) {
      existingUser.provider = provider;
      existingUser.providerId = profile.providerId;
      await this.userRepository.save(existingUser);
      return this.sessionService.issueSession(existingUser);
    }

    const newUser = await this.userRepository.save(
      this.userRepository.create({
        provider,
        providerId: profile.providerId,
        email: profile.email,
      }),
    );
    return this.sessionService.issueSession(newUser);
  }

  private async mockLogin(email: string) {
    this.logger.warn(`MOCK_AUTH bypass used for ${email}`);
    const user = await this.userRepository.findOne({ where: { email } });
    return this.sessionService.issueSession(user);
  }
}

import { Server, Socket } from 'socket.io';
import {
  ConnectedSocket,
  MessageBody,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';

interface Message {
  seq: number;
  from: string;
  body: string;
  ts: number;
}

// Per-room message log. Each room's array grows completely independently
// of every other room — there is nothing here that ties memory usage to
// how many rooms exist or how long the process has been running.
const roomLog = new Map<string, Message[]>();

// Monotonic counter shared by every room. Only ever used for ordering
// today — nothing reads it back as a pagination cursor into any
// durable store, because there isn't one.
let seq = 0;

@WebSocketGateway()
export class ChatGateway {
  @WebSocketServer()
  server: Server;

  @SubscribeMessage('message')
  onMessage(
    @MessageBody() data: { roomId: string; from: string; body: string },
    @ConnectedSocket() client: Socket,
  ): void {
    const { roomId, from, body } = data;

    const log = roomLog.get(roomId) ?? [];

    const msg: Message = {
      seq: ++seq,
      from,
      body,
      ts: Date.now(),
    };

    // Append path: the log only ever grows. Nothing here caps its
    // length or evicts the oldest entries once some threshold is
    // crossed, so a busy, long-lived room accumulates messages forever.
    log.push(msg);
    roomLog.set(roomId, log);

    this.server.to(roomId).emit('message', msg);
  }

  @SubscribeMessage('reconnect')
  onReconnect(
    @MessageBody() data: { roomId: string; lastSeq: number },
    @ConnectedSocket() client: Socket,
  ): { missed: Message[] } {
    const { roomId, lastSeq } = data;

    const log = roomLog.get(roomId) ?? [];

    // Replay path: return everything newer than what the client last
    // saw, whole. Size scales with how long the client was offline
    // times how chatty the room is — nothing here caps the batch.
    const missed = log.filter((m) => m.seq > lastSeq);

    client.join(roomId);

    return { missed };
  }
}

// chat.gateway.ts — server
import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  ConnectedSocket,
  MessageBody,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';

interface JoinPayload {
  roomId: string;
  userId: string;
}

interface TypingPayload {
  roomId: string;
  userId: string;
}

@WebSocketGateway({ cors: true })
export class ChatGateway {
  @WebSocketServer()
  server: Server;

  // Presence: a joiner's own client should ALSO see itself appear
  // online right away, so including the emitter here is intentional.
  @SubscribeMessage('join')
  handleJoin(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: JoinPayload,
  ): void {
    client.join(payload.roomId);
    this.server.to(payload.roomId).emit('presence', {
      roomId: payload.roomId,
      userId: payload.userId,
      status: 'online',
    });
  }

  // Typing: meant to notify everyone else in the room that this user
  // is typing right now. The typer already knows they're typing from
  // their own local input state, so they should not receive it back.
  @SubscribeMessage('typing')
  handleTyping(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: TypingPayload,
  ): void {
    this.server.to(payload.roomId).emit('typing', { userId: payload.userId });
  }
}

// useTypingIndicator.ts — client
import { useEffect, useRef, useState } from 'react';
import type { Socket } from 'socket.io-client';

const TYPING_CLEAR_MS = 2500;

export function useTypingIndicator(socket: Socket): string | null {
  const [typingUser, setTypingUser] = useState<string | null>(null);
  const clearTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const handleTyping = ({ userId }: { userId: string }): void => {
      // Renders whatever userId arrives — no special-casing of "self".
      setTypingUser(userId);

      if (clearTimer.current) {
        clearTimeout(clearTimer.current);
      }
      // Ephemeral by design: no store write, no persistence. If no new
      // 'typing' event shows up in time, the indicator just fades.
      clearTimer.current = setTimeout(() => {
        setTypingUser(null);
      }, TYPING_CLEAR_MS);
    };

    socket.on('typing', handleTyping);

    return () => {
      socket.off('typing', handleTyping);
      if (clearTimer.current) clearTimeout(clearTimer.current);
    };
  }, [socket]);

  return typingUser;
}

// ChatRoom.tsx — client render (for reference, not the fault)
function TypingBanner({ typingUser }: { typingUser: string | null }) {
  if (!typingUser) return null;
  return <p className="typing-banner">{typingUser} is typing…</p>;
}

import { Injectable, Controller, Get, Param } from '@nestjs/common';
import { Pool } from 'pg';

interface Profile {
  id: string;
  displayName: string;
  bio: string;
  avatarUrl: string;
  updatedAt: Date;
}

interface ProfilePatch {
  displayName?: string;
  bio?: string;
  avatarUrl?: string;
}

@Injectable()
export class ProfileRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Profile | null> {
    const result = await this.pool.query(
      `SELECT id, display_name AS "displayName", bio,
              avatar_url AS "avatarUrl", updated_at AS "updatedAt"
       FROM profiles WHERE id = $1`,
      [id],
    );
    return result.rows[0] ?? null;
  }

  async update(id: string, patch: ProfilePatch): Promise<void> {
    await this.pool.query(
      `UPDATE profiles
       SET display_name = COALESCE($2, display_name),
           bio = COALESCE($3, bio),
           avatar_url = COALESCE($4, avatar_url),
           updated_at = NOW()
       WHERE id = $1`,
      [id, patch.displayName ?? null, patch.bio ?? null, patch.avatarUrl ?? null],
    );
  }
}

// Production traffic on this service is read:write ~10:1 — updateProfile
// fires far less often than getProfile, but every single read below still
// costs a full DB round-trip, and there is nothing between this service
// and Postgres to absorb repeated lookups of the same hot id.
@Injectable()
export class ProfileService {
  constructor(private readonly profileRepo: ProfileRepository) {}

  /** Hot path: called on nearly every request. */
  async getProfile(id: string): Promise<Profile | null> {
    return this.profileRepo.findById(id);
  }

  /** Rare path: writes are ~10x less frequent than reads. */
  async updateProfile(id: string, patch: ProfilePatch): Promise<void> {
    await this.profileRepo.update(id, patch);
  }
}

@Controller('profiles')
export class ProfileController {
  constructor(private readonly profileService: ProfileService) {}

  @Get(':id')
  async getById(@Param('id') id: string): Promise<Profile | null> {
    return this.profileService.getProfile(id);
  }
}

import { Controller, Post, Body, Param } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

interface PostEntity {
  id: string;
  authorId: string;
  body: string;
  createdAt: Date;
}

interface TimelineEntry {
  userId: string;
  postId: string;
  createdAt: Date;
}

interface FollowRepository {
  // Returns every follower id of the author — array length === follower count.
  findFollowerIds(authorId: string): Promise<string[]>;
}

@Controller('posts')
export class PostsController {
  constructor(
    @InjectRepository(PostEntity)
    private readonly postRepository: Repository<PostEntity>,
    private readonly followRepository: FollowRepository,
    @InjectRepository(TimelineEntry)
    private readonly timelineRepository: Repository<TimelineEntry>,
  ) {}

  @Post(':authorId')
  async createPost(
    @Param('authorId') authorId: string,
    @Body() body: { content: string },
  ) {
    // 1. Persist the post.
    const post = await this.postRepository.save({
      authorId,
      body: body.content,
      createdAt: new Date(),
    });

    // 2. Load the author's followers.
    const followers = await this.followRepository.findFollowerIds(authorId);

    // 3. Fan the post out to every follower's timeline, one write at a
    //    time, INLINE on the request path — no follower-count check
    //    anywhere, so a celebrity author drives the exact same loop as
    //    an author with two followers.
    for (const followerId of followers) {
      await this.timelineRepository.insert({
        userId: followerId,
        postId: post.id,
        createdAt: post.createdAt,
      });
    }

    // 4. Only returns once every follower's timeline write has completed.
    return { status: 201, post };
  }
}

import { Entity, PrimaryGeneratedColumn, Column, Repository } from "typeorm"
import { Injectable } from "@nestjs/common"
import { InjectRepository } from "@nestjs/typeorm"

/**
 * A chunk manifest entry, stored inline inside the `chunks` JSONB column below.
 * There is no dedicated table for this — it only ever exists as an array element.
 */
interface ChunkManifestEntry {
    chunkIndex: number
    sha256: string
    sizeBytes: number
    uploaded: boolean
}

@Entity("files")
export class File {
    @PrimaryGeneratedColumn("uuid")
        id: string

    @Column()
        filename: string

    @Column()
        ownerId: string

    @Column("bigint")
        sizeBytes: number

    // Standalone counter, kept alongside the array below.
    // Nothing enforces that this stays equal to `chunks.length`.
    @Column("int")
        chunkCount: number

    // The ENTIRE per-file chunk manifest, packed into one JSONB blob on the file row.
    // sha256 and chunkIndex exist only as fields inside array elements —
    // neither is a real, indexable column.
    @Column({ type: "jsonb" })
        chunks: ChunkManifestEntry[]
}

@Injectable()
export class FileService {
    public constructor(
        @InjectRepository(File)
        private readonly fileRepository: Repository<File>
    ) {}

    /**
     * Marks a single chunk as uploaded once its bytes have landed in blob storage.
     */
    public async markChunkUploaded(
        fileId: string,
        chunkIndex: number,
        sha256: string
    ): Promise<void> {
        const file = await this.fileRepository.findOneBy({ id: fileId })
        if (!file) {
            throw new Error(`File ${fileId} not found`)
        }

        // Read-parse-mutate-rewrite of the WHOLE chunks array for a single-chunk update.
        const chunk = file.chunks.find((c) => c.chunkIndex === chunkIndex)
        if (!chunk) {
            throw new Error(`Chunk ${chunkIndex} not found on file ${fileId}`)
        }
        chunk.uploaded = true
        chunk.sha256 = sha256

        // Persists the entire chunks array back. Two concurrent calls for two
        // different chunkIndex values can both read before either writes,
        // so one update silently overwrites the other.
        await this.fileRepository.save(file)
    }

    /**
     * Global dedup lookup: does a chunk with this sha256 already exist anywhere
     * across every file? Used before accepting a chunk upload.
     */
    public async findChunkBySha256(sha256: string): Promise<File[]> {
        // sha256 is not a real column, so this has to unnest and inspect every
        // row's JSONB array — a full scan that gets worse as `files` grows.
        return this.fileRepository
            .createQueryBuilder("file")
            .where(
                `EXISTS (
                    SELECT 1 FROM jsonb_array_elements(file.chunks) AS c
                    WHERE c->>'sha256' = :sha256
                )`,
                { sha256 }
            )
            .getMany()
    }

    /**
     * Resume support: which chunkIndex values are still missing/not uploaded
     * for this file? Same structural problem — no index to answer it.
     */
    public async getMissingChunkIndexes(fileId: string): Promise<number[]> {
        const file = await this.fileRepository.findOneBy({ id: fileId })
        if (!file) {
            throw new Error(`File ${fileId} not found`)
        }

        return file.chunks
            .filter((c) => !c.uploaded)
            .map((c) => c.chunkIndex)
    }
}

