@Injectable()
export class CrawlerStorageService {
    constructor(
        @InjectRepository(CrawledPage)
        private readonly repository: Repository<CrawledPage>
    ) {}

    // Writes the fetched page straight into the hot table, htmlBody and all.
    async save(page: FetchedPage): Promise<CrawledPage> {
        const entity = this.repository.create({
            url: page.url,
            host: page.host,
            statusCode: page.statusCode,
            htmlBody: page.html,
            crawledAt: new Date()
        })

        return this.repository.save(entity)
    }

