    async findRecentByHost(host: string): Promise<Array<Partial<CrawledPage>>> {
        return this.repository.find({
            where: { host },
            select: ["url", "host", "statusCode", "crawledAt"],
            order: { crawledAt: "DESC" },
            take: 50
        })
    }

