        return this.repository.count({ where: { statusCode } })
    }
}

import { Injectable, OnModuleInit } from '@nestjs/common';
import { WebSocketGateway, WebSocketServer } from '@nestjs/websockets';
import { Server } from 'socket.io';
import Redis from 'ioredis';

interface ChatMessage {
  roomId: string;
  payload: unknown;
}

/**
 * Fans out chat messages published on Redis to every gateway instance,
 * each of which delivers to the sockets it currently holds.
 */
@Injectable()
@WebSocketGateway({ cors: true })
export class ChatGateway implements OnModuleInit {
  @WebSocketServer()
  server: Server;

  private readonly subscriber = new Redis(process.env.REDIS_URL);

  onModuleInit(): void {
    this.subscriber.psubscribe('room:*:messages');

    this.subscriber.on('pmessage', (_pattern: string, _channel: string, raw: string) => {
      const message = JSON.parse(raw) as ChatMessage;
      this.deliver(message.roomId, message.payload);
    });
  }

  /**
   * Delivers a single chat message to every socket currently joined to `roomId`.
   * Runs once per incoming Redis message — in a hot room this fires N times
   * back-to-back, each call re-encoding the payload and walking every socket
   * in the room to write the frame.
   */
  deliver(roomId: string, payload: unknown): void {
    this.server.to(roomId).emit('message', payload);
  }
}

