import { Processor, WorkerHost } from '@nestjs/bullmq'
import { Injectable, Logger } from '@nestjs/common'
import { InjectQueue } from '@nestjs/bullmq'
import { Job, Queue } from 'bullmq'

const CONCURRENCY = 1

@Injectable()
@Processor('dispatch', { concurrency: CONCURRENCY })
export class DispatchWorker extends WorkerHost {
  private readonly logger = new Logger(DispatchWorker.name)

  constructor(
    @InjectQueue('dispatch') private readonly dispatchQueue: Queue,
  ) {
    super()
  }

  async process(job: Job): Promise<void> {
    const { channel, payload } = job.data

    try {
      const message = this.renderTemplate(channel, payload)
      await this.dispatchMessage(channel, message)
    } catch (err) {
      this.logger.error(`dispatch failed for job ${job.id}, re-queueing`, err)
      // Retry by hand: push a brand-new job with the same data back onto
      // the queue. There is no attempt cap here, so a payload that always
      // fails to render just loops forever, occupying this worker slot.
      await this.dispatchQueue.add('send-notification', job.data)
    }
  }

  private renderTemplate(channel: string, payload: any): string {
    if (!payload || !payload.recipient) {
      throw new Error('invalid payload: missing recipient')
    }

    switch (channel) {
      case 'email':
        return `Email to ${payload.recipient}: ${payload.body}`
      case 'sms':
        return `SMS to ${payload.recipient}: ${payload.body}`
      case 'push':
        return `Push to ${payload.recipient}: ${payload.body}`
      default:
        throw new Error(`unknown channel: ${channel}`)
    }
  }

  private async dispatchMessage(channel: string, message: string): Promise<void> {
    // Sends `message` out over the given channel's provider.
    this.logger.log(`[${channel}] ${message}`)
  }
}

