interface Bucket {
  tokens: number;
  lastRefill: number;
}

/**
 * Per-user, per-channel token-bucket rate limiter for the
 * notification-send endpoint.
 */
class NotificationRateLimiter {
  // Remaining-token state lives only in this process's memory.
  private buckets = new Map<string, Bucket>();

  constructor(
    private readonly capacity: number,      // max tokens = the intended limit
    private readonly refillRate: number,    // tokens added per second
  ) {}

  /**
   * Returns true if the request for `userId` on `channel` is allowed,
   * false if it should be rejected (rate limited).
   */
  async allow(userId: string, channel: string): Promise<boolean> {
    const key = `${userId}:${channel}`;
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill based on elapsed time since last check.
    const elapsedSeconds = (now - bucket.lastRefill) / 1000;
    const refillAmount = elapsedSeconds * this.refillRate;
    bucket.tokens = Math.min(this.capacity, bucket.tokens + refillAmount);
    bucket.lastRefill = now;

    // Audit-log the check before deciding (async I/O in between read and write).
    await auditLog.record(userId, channel, bucket.tokens);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      this.buckets.set(key, bucket);
      return true;
    }

    return false;
  }
}

const limiter = new NotificationRateLimiter(/* capacity */ 5, /* refillRate */ 1);

// Express-style middleware on the notification-send endpoint.
async function sendNotificationHandler(req: Request, res: Response) {
  const { userId, channel } = req.body;

  if (!(await limiter.allow(userId, channel))) {
    return res.status(429).send({ error: 'Rate limit exceeded, try again later.' });
  }

  await notificationProvider.send(req.body);
  return res.status(200).send({ status: 'sent' });
}

import { randomUUID } from 'crypto';
import { Injectable, OnModuleInit, Controller, Post, Get, Body } from '@nestjs/common';
import { Kafka, Consumer, Producer, EachMessagePayload } from 'kafkajs';

interface ClickEvent {
  eventId: string;
  adId: string;
}

// In-memory dedup + counting state — wiped whenever the process restarts.
const seen = new Set<string>();
const counts = new Map<string, number>();

@Injectable()
export class AdClickConsumerService implements OnModuleInit {
  private readonly kafka = new Kafka({
    clientId: 'ad-click-service',
    brokers: [process.env.KAFKA_BROKER ?? 'localhost:9092'],
  });

  private consumer: Consumer;
  private producer: Producer;

  async onModuleInit(): Promise<void> {
    // BUG: a fresh groupId is minted on every boot, so Kafka has no
    // committed offset to hand back for this "new" group.
    this.consumer = this.kafka.consumer({
      groupId: `ad-click-counter-${Date.now()}`,
    });

    this.producer = this.kafka.producer();
    await this.producer.connect();

    await this.consumer.connect();
    // With no committed offset for the brand-new group, fromBeginning
    // makes the consumer replay the entire topic from offset 0.
    await this.consumer.subscribe({ topic: 'ad-clicks', fromBeginning: true });

    await this.consumer.run({
      eachMessage: async ({ message }: EachMessagePayload) => {
        if (!message.value) return;

        const event = JSON.parse(message.value.toString()) as ClickEvent;

        if (seen.has(event.eventId)) {
          return;
        }

        seen.add(event.eventId);
        counts.set(event.adId, (counts.get(event.adId) ?? 0) + 1);
      },
    });
  }

  async produceClick(adId: string): Promise<ClickEvent> {
    const event: ClickEvent = { eventId: randomUUID(), adId };

    await this.producer.send({
      topic: 'ad-clicks',
      messages: [{ value: JSON.stringify(event) }],
    });

    return event;
  }

  getCounts(): Record<string, number> {
    return Object.fromEntries(counts);
  }
}

@Controller('clicks')
export class AdClickController {
  constructor(private readonly service: AdClickConsumerService) {}

  @Post()
  async postClick(@Body('adId') adId: string): Promise<ClickEvent> {
    return this.service.produceClick(adId);
  }
}

@Controller('counts')
export class AdCountsController {
  constructor(private readonly service: AdClickConsumerService) {}

  @Get()
  getCounts(): Record<string, number> {
    return this.service.getCounts();
  }
}

interface ClickEvent {
  clickId: string;
  adId: string;
  eventMs: number; // event-time epoch millis, as carried on the Kafka record
}

type Classification = "accepted" | "late";

/**
 * Watermark-driven stream processor for the ad-click aggregator.
 * The watermark is supposed to be a monotonic high-water mark of event
 * time: it tells downstream fraud-detection when a window is safe to
 * close, and it's the yardstick used to classify incoming clicks.
 */
export class ClickAggregator {
  private watermarkMs = 0;

  // Allowed lateness: events older than (watermark - tolerance) are late.
  private readonly tolerance = 5000;

  private readonly windowSizeMs = 60000;

  // window start -> count of accepted clicks in that window.
  // NOTE: entries are never evicted once written.
  private readonly windowCounts: Map<number, number> = new Map();

  processClick(event: ClickEvent): Classification {
    // Advance the high-water mark to the latest event time seen.
    this.watermarkMs = event.eventMs;

    if (event.eventMs < this.watermarkMs - this.tolerance) {
      return "late";
    }

    const windowStart = Math.floor(event.eventMs / this.windowSizeMs) * this.windowSizeMs;
    const current = this.windowCounts.get(windowStart) ?? 0;
    this.windowCounts.set(windowStart, current + 1);

    return "accepted";
  }

  getWatermark(): number {
    return this.watermarkMs;
  }

  getWindowCount(windowStart: number): number {
    return this.windowCounts.get(windowStart) ?? 0;
  }
}

type AccountEventType = "AccountDeposited" | "AccountWithdrawn";

interface AccountEvent {
  accountId: string;
  version: number; // monotonically increasing, 1..n — never mutated or deleted
  type: AccountEventType;
  payload: { amount: number };
}

interface AccountAggregate {
  accountId: string;
  balance: number;
  version: number;
}

/**
 * Append-only event log — the single source of truth for account state.
 */
class EventStore {
  private readonly eventsByAccount = new Map<string, AccountEvent[]>();

  appendEvent(accountId: string, type: AccountEventType, amount: number): AccountEvent {
    const events = this.eventsByAccount.get(accountId) ?? [];
    const event: AccountEvent = {
      accountId,
      version: events.length + 1,
      type,
      payload: { amount },
    };
    events.push(event);
    this.eventsByAccount.set(accountId, events);
    return event;
  }

  getEvents(accountId: string): AccountEvent[] {
    return this.eventsByAccount.get(accountId) ?? [];
  }
}

function initialState(accountId: string): AccountAggregate {
  return { accountId, balance: 0, version: 0 };
}

/**
 * Pure reducer: folds a single event into aggregate state.
 */
function apply(state: AccountAggregate, event: AccountEvent): AccountAggregate {
  const balance =
    event.type === "AccountDeposited"
      ? state.balance + event.payload.amount
      : state.balance - event.payload.amount;

  return { accountId: state.accountId, balance, version: event.version };
}

class AccountService {
  constructor(private readonly eventStore: EventStore) {}

  deposit(accountId: string, amount: number): void {
    this.eventStore.appendEvent(accountId, "AccountDeposited", amount);
  }

  withdraw(accountId: string, amount: number): void {
    this.eventStore.appendEvent(accountId, "AccountWithdrawn", amount);
  }

  /**
   * Hot read path: loads ALL n events for the account and folds them
   * from version 1 on every single call. O(n) per read — cost grows
   * unbounded as the append-only log keeps lengthening, even though
   * callers only ever want the current balance.
   */
  loadAccount(accountId: string): AccountAggregate {
    const events = this.eventStore.getEvents(accountId);
    return events.reduce(apply, initialState(accountId));
  }

  getBalance(accountId: string): number {
    return this.loadAccount(accountId).balance;
  }
}

