import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

@Injectable()
export class EmailQueueService {
  constructor(
    @InjectQueue('emails') private readonly emailsQueue: Queue,
  ) {}

  async enqueueWelcomeEmail(userId: string): Promise<void> {
    // Deterministic id derived from the logical unit of work.
    // jobId makes this idempotent — BullMQ won't add a duplicate
    // while a job with this id already exists in the queue.
    const jobId = `welcome:${userId}`;

    await this.emailsQueue.add(
      'send-welcome',
      { userId },
      {
        jobId,
        // Drop finished jobs immediately so Redis history doesn't
        // grow unbounded — we don't need completed jobs lying around.
        removeOnComplete: true,
        removeOnFail: false,
      },
    );
  }
}

