    await this.mailer.sendWelcome(job.data.userId);
  }
}

import { createClient, RedisClientType } from "redis";

const SNAPSHOT_KEY = "autocomplete:trie:snapshot";

/**
 * A single node in the prefix Trie.
 */
interface TrieNode {
  children: Map<string, TrieNode>;
  isWord: boolean;
  frequency: number;
}

function createNode(): TrieNode {
  return { children: new Map(), isWord: false, frequency: 0 };
}

/**
 * In-memory search-autocomplete service backed by a Redis snapshot.
 */
export class SuggestService {
  private root: TrieNode = createNode();
  private redis: RedisClientType;

  constructor(redis: RedisClientType) {
    this.redis = redis;
  }

  /**
   * Records that `term` was searched: walks/creates nodes for every
   * character, bumps the terminal node's frequency, then persists.
   */
  async recordQuery(term: string): Promise<void> {
    let node = this.root;
    for (const ch of term) {
      let child = node.children.get(ch);
      if (!child) {
        child = createNode();
        node.children.set(ch, child);
      }
      node = child;
    }
    node.isWord = true;
    node.frequency += 1;

    // Every single recorded query re-serializes and rewrites the ENTIRE tree.
    await this.persistState();
  }

  /**
   * Serializes the WHOLE Trie to JSON and writes it under one Redis key.
   */
  private async persistState(): Promise<void> {
    const serialized = JSON.stringify(this.root, (_key, value) => {
      if (value instanceof Map) {
        return Object.fromEntries(value);
      }
      return value;
    });
    await this.redis.set(SNAPSHOT_KEY, serialized);
  }

  /**
   * Rebuilds the in-memory Trie from the last full snapshot in Redis.
   */
  async loadState(): Promise<void> {
    const serialized = await this.redis.get(SNAPSHOT_KEY);
    if (!serialized) {
      this.root = createNode();
      return;
    }
    const raw = JSON.parse(serialized);
    this.root = this.reviveNode(raw);
  }

  private reviveNode(raw: any): TrieNode {
    const node: TrieNode = {
      children: new Map(),
      isWord: raw.isWord,
      frequency: raw.frequency,
    };
    for (const [ch, childRaw] of Object.entries(raw.children ?? {})) {
      node.children.set(ch, this.reviveNode(childRaw));
    }
    return node;
  }

  /**
   * Returns the top-K completions for `prefix`, ranked by frequency.
   */
  getSuggestions(prefix: string, k: number): string[] {
    let node = this.root;
    for (const ch of prefix) {
      const child = node.children.get(ch);
      if (!child) {
        return [];
      }
      node = child;
    }

    const results: Array<{ word: string; frequency: number }> = [];
    this.collectWords(node, prefix, results);

    results.sort((a, b) => b.frequency - a.frequency);
    return results.slice(0, k).map((r) => r.word);
  }

  private collectWords(
    node: TrieNode,
    prefixSoFar: string,
    out: Array<{ word: string; frequency: number }>,
  ): void {
    if (node.isWord) {
      out.push({ word: prefixSoFar, frequency: node.frequency });
    }
    for (const [ch, child] of node.children) {
      this.collectWords(child, prefixSoFar + ch, out);
    }
  }
}

async function main() {
  const redis: RedisClientType = createClient();
  await redis.connect();

  const service = new SuggestService(redis);
  await service.loadState();

  // Every one of these calls triggers a full-tree JSON.stringify + Redis SET,
  // and every distinct term — including one-off long-tail searches — lives
  // in the Trie (and the snapshot) forever.
  await service.recordQuery("react");
  await service.recordQuery("redis");
  await service.recordQuery("redux");

  console.log(service.getSuggestions("re", 5));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
